ee:message.ee:set-payload:
%dw 2.0
output application/json
var customers = {
	"CUS-100": { name: "Ana Lima", tier: "GOLD", shippingAddress: { street: "Rua A, 1", city: "Sao Paulo", country: "BR" } },
	"CUS-200": { name: "John Smith", tier: "STANDARD", shippingAddress: { street: "1 Main St", city: "Austin", country: "US" } }
}
var id = attributes.uriParams.customerId
---
if (id startsWith "CUS-DOWN") { error: "CRM unavailable" }
else if (customers[id] == null) { error: "customer " ++ id ++ " not found" }
else { customer: { id: id } ++ customers[id], meta: { source: "CRM", fetchedAt: now() as String } }
